using AiCare.Application.Accounting;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Logging;using System.Data.Common;
namespace AiCare.Infrastructure.Accounting;
public sealed class AccountingOutboxWorker(IServiceScopeFactory scopes,ILogger<AccountingOutboxWorker> log):BackgroundService
{
 protected override async Task ExecuteAsync(CancellationToken stop){while(!stop.IsCancellationRequested){try{await Cycle(stop);}catch(OperationCanceledException)when(stop.IsCancellationRequested){break;}catch(Exception e){log.LogError(e,"Accounting outbox cycle failed.");}await Task.Delay(TimeSpan.FromSeconds(10),stop);}}
 async Task Cycle(CancellationToken t){await using var scope=scopes.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CareDbContext>();var providers=scope.ServiceProvider.GetServices<IAccountingProvider>().ToDictionary(x=>x.Name,StringComparer.OrdinalIgnoreCase);var ids=new List<Guid>();await using(var c=await Cmd(db,"select o.id from accounting_outbox o join accounting_connections c on c.organization_id=o.organization_id and c.provider=o.provider where c.status='Active' and c.sync_enabled and o.status in ('Pending','Retrying') and (o.next_attempt_at is null or o.next_attempt_at<=now()) order by o.created_at for update skip locked limit 10",t)){await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t))ids.Add(r.GetGuid(0));}foreach(var id in ids)await Process(db,providers,id,t);}
 async Task Process(CareDbContext db,IReadOnlyDictionary<string,IAccountingProvider> providers,Guid id,CancellationToken t){Outbox x;await using(var c=await Cmd(db,"select o.organization_id,o.provider,o.entity_type,o.entity_id,o.idempotency_key,o.attempt_count,c.credential_reference,c.external_tenant_id from accounting_outbox o join accounting_connections c on c.organization_id=o.organization_id and c.provider=o.provider and c.status='Active' and c.sync_enabled where o.id=@id",t,("id",id))){await using var r=await c.ExecuteReaderAsync(t);if(!await r.ReadAsync(t))return;x=new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetGuid(3),r.GetString(4),r.GetInt32(5),r.GetString(6),r.GetString(7));}await Exec(db,"update accounting_outbox set status='Processing',attempt_count=attempt_count+1,last_attempt_at=now() where id=@id",t,("id",id));try{if(!providers.TryGetValue(x.Provider,out var p))throw new InvalidOperationException("Accounting provider is not registered.");var command=new AccountingSyncCommand(x.Organization,x.EntityId,x.Key,x.Credential,x.Tenant);var result=x.EntityType switch{"Funder"=>await p.SyncContactAsync(command,t),"Invoice"=>await p.SyncInvoiceAsync(command,t),"CreditNote"=>await p.SyncCreditNoteAsync(command,t),"Payment"=>await p.SyncPaymentAsync(command,t),_=>throw new InvalidOperationException("Unsupported accounting entity.")};await Exec(db,"insert into accounting_mappings(id,organization_id,provider,local_entity_type,local_entity_id,external_entity_id) values(gen_random_uuid(),@org,@provider,@type,@entity,@external) on conflict(organization_id,provider,local_entity_type,local_entity_id) do update set external_entity_id=excluded.external_entity_id;update accounting_outbox set status='Succeeded',last_success_at=now(),sanitized_error='' where id=@id",t,("id",id),("org",x.Organization),("provider",x.Provider),("type",x.EntityType),("entity",x.EntityId),("external",result.ExternalId));}catch(Exception e){var attempt=x.Attempts+1;var failed=attempt>=5;var safe=e is InvalidOperationException?e.Message:"Provider operation failed.";await Exec(db,"update accounting_outbox set status=@status,next_attempt_at=case when @failed then null else now()+make_interval(mins=>@delay) end,sanitized_error=@error where id=@id",t,("id",id),("status",failed?"Failed":"Retrying"),("failed",failed),("delay",Math.Min(60,(int)Math.Pow(2,attempt))),("error",safe[..Math.Min(safe.Length,500)]));}}
 static async Task<DbCommand>Cmd(CareDbContext db,string sql,CancellationToken t,params(string,object)[] values){var n=db.Database.GetDbConnection();if(n.State!=System.Data.ConnectionState.Open)await n.OpenAsync(t);var c=n.CreateCommand();c.CommandText=sql;foreach(var v in values)Add(c,v.Item1,v.Item2);return c;}static async Task Exec(CareDbContext db,string sql,CancellationToken t,params(string,object)[] values){await using var c=await Cmd(db,sql,t,values);await c.ExecuteNonQueryAsync(t);}static void Add(DbCommand c,string n,object?v){var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}sealed record Outbox(Guid Organization,string Provider,string EntityType,Guid EntityId,string Key,int Attempts,string Credential,string Tenant);
}
